def count_up_to(n):
    """
    This function takes a non-negative integer n and returns a list of all prime numbers less than n.
    """
    def is_prime(num):
        """Helper function to check if a number is prime."""
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Handle edge cases: if n is 0 or 1, return an empty list since there are no primes less than these values.
    if n <= 1:
        return []

    # Generate a list of prime numbers less than n.
    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)

    return primes
